# 		1. List the number of films per category.

select c.name,
	   count(f.film_id) as total_per_category
from category c
inner join film_category f
on c.category_id = f.category_id
group by c.name;

# 		2. Retrieve the store ID, city, and country for each store.

select s.store_id,
	   a.city_id,
       c.city,
       p.country
from store s
left join (address a, city c, country p)
on s.store_id = a.address_id and a.city_id = c.city and c.country_id = p.country;


# 			3. Calculate the total revenue generated by each store in dollars.

select s.store_id,
	   sum(p.amount) as total_rev_dollar
from staff s
left join payment p
on s.store_id = p.staff_id
group by s.store_id;

# 			4. Determine the average running time of films for each category.

select avg(f.length), 
       c.name
from category c
inner join (film f,
		   film_category fc)
on f.film_id = fc.film_id
group by c.name;

